	_auto_set([Vector3(0, 1.11, -3.0), Vector3(0, 1.11, -5.0), Vector3(4.0, 1.11, -5.0), Vector3(4.0, 1.11, 34.5), Vector3(0, 1.11, 34.5)], PI)

